import type { MediaFile } from '@shared/types/media';
import { formatDuration } from '@shared/utils/time';
import { useThumbnail } from '../../hooks/useThumbnail';
import { Icon } from '../../lib/Icon';
import { Skeleton } from '../ui/Feedback';
import styles from './FileCard.module.css';

const KIND_ICONS = { video: 'Film', audio: 'FileMusic', image: 'Image', subtitle: 'Captions', unknown: 'File' } as const;

/** A frame from the file (generated by FFmpeg), or an icon for files without a picture. */
export function FileThumbnail({ file }: { file: MediaFile }): React.JSX.Element {
  const thumbnail = useThumbnail(file.probeError ? null : file.path);
  return (
    <div className={styles.thumb}>
      {thumbnail.status === 'loading' && <Skeleton width="100%" height="100%" radius={0} />}
      {thumbnail.status === 'ready' && <img src={thumbnail.src} alt="" draggable={false} />}
      {thumbnail.status === 'none' && (
        <div className={styles.placeholder}>
          <Icon name={file.probeError ? 'FileExclamationPoint' : KIND_ICONS[file.kind]} size={20} />
        </div>
      )}
      {file.duration != null && file.kind !== 'image' && <span className={styles.duration}>{formatDuration(file.duration)}</span>}
    </div>
  );
}
